import{_ as e,c as t,o,ag as s}from"./chunks/framework.BwVZiZlf.js";const u=JSON.parse('{"title":"A Busy but Happy Day","description":"","frontmatter":{"title":"A Busy but Happy Day","date":"2025-04-04T00:00:00.000Z"},"headers":[],"relativePath":"blog/2025/04/04/a-busy-happy-day.md","filePath":"blog/2025/04/04/a-busy-happy-day.md","lastUpdated":1786674252000}'),i={name:"blog/2025/04/04/a-busy-happy-day.md"};function n(d,a,r,p,y,l){return o(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1743724800000"},a[0]||(a[0]=[s('<h1 id="a-busy-but-happy-day" tabindex="-1">A Busy but Happy Day <a class="header-anchor" href="#a-busy-but-happy-day" aria-label="Permalink to &quot;A Busy but Happy Day&quot;">​</a></h1><p>This morning, I got up at 6 o&#39;clock. I cooked porridge and transferred some downloaded child-friendly documentaries to our family SMB server, so my kids and I could watch them together later.</p><p>After that, I updated the VitePress theme to make writing my blog more efficient.</p><p>I went out to buy some KFC and coffee for my wife, since she doesn’t eat porridge.</p><p>Later, I replaced the cabin air filter by myself, which saved me 1,000 yuan. It took me two hours to finish because it was my first time doing it — but I think it was worth it.</p><p>I also made lunch myself. I accidentally added too much salt and felt a bit salty, but I’ve always believed that cooking my own food is healthier and safer. Food safety is a serious issue in China.</p><p>In the afternoon, I played badminton with my son for an hour. It was really fun and even attracted some neighbors to watch.</p><p>Then we watched a BBC children’s documentary about life in Antarctica.</p><p>Now I’m writing this blog while my son is resting (he&#39;s asleep). Although it’s been a busy day, it’s also been full and enjoyable.<br> Thank God I lived another day.</p>',9)]))}const c=e(i,[["render",n]]);export{u as __pageData,c as default};
